/*==========================================================================*/
/*        I N L I N E   F U N C T I O N S   &   T E M P L A T E S           */
/*==========================================================================*/
void hobp_trace (void)
{  
  static Boolean do_init = TRUE ;

  if(do_init)
    {
      do_init = FALSE ;

      _do_init_() ;

    }

  os_tsk_start (tsk, 0) ;

}
//--------------------------------------------------------------------------//

static void _do_init_(void)
{
  UInt8 n ;

  tsk = os_tsk_create (hobp_trace_task , TASK_HOBP_TRACE_PRI , TASK_HOBP_TRACE_STK , 0 , TASK_HOBP_TRACE_NAME) ;
  
  q_free    = q_create() ;

  for(n = 0 ; n < 7 ; n++)
    {
      Q_Msg * q_msg = (Q_Msg *) os_mem_request (sizeof (Hobp_Bus_Rx_Q_Msg)) ;
      
      if(q_msg)
        {
          q_assign (q_free , q_msg) ;
          q_insert (q_free , q_msg) ;
        }
    }
    
}

//--------------------------------------------------------------------------//
static void hobp_trace_task(void * arg)
{
  UInt32 trace_i ;

//  hobp_msg[HOBP_MSG_ECM].data[2]= 0x39 ;

  for(trace_i = 0 ; trace_i < sizeof_array(trace_msg) ; trace_i++)
    {
      if(!hobp_log_is_done())
        {
          UInt8 n ;
 
          #if DBG_HOBP == 1
            hobp_dbg_print("\nHobp Trace     :"     , &trace_msg[trace_i].data[0] , trace_msg[trace_i].size)        ;// 
          #endif
 
          for (n = 0 ; n < trace_msg[trace_i].size ; n++)
            {
              Hobp_Bus_Rx_Q_Msg * q_msg = (Hobp_Bus_Rx_Q_Msg *) q_remove (q_free ,NULL);
              
              q_msg->data = trace_msg[trace_i].data[n] ;
              
              q_insert (hobp_vars.rx_q_pending , (Q_Msg *)q_msg) ;
    
            }
    
          os_tsk_wait(50) ;
        }
    }

  #if DBG_HOBP == 1
    hobp_dbg_print("\n\nHobp Trace Done\n\n",NULL ,NULL)        ;// 
  #endif

}
